import re
import difflib
from typing import Any, Dict, List, Optional


# =============================================================================
# P4 - CATÁLOGO FUENTE DE COMPATIBILIDAD FLUIDO / MATERIAL
# -----------------------------------------------------------------------------
# Base: tabla de compatibilidad del proveedor DMH con 24 celdas corregidas el 30/10/2026
# con Aero Rubber, ISM y Little Giant (cada celda corregida lleva su comentario en el diccionario).
#
# Principios:
# 1. Conservar la tabla DMH; solo difieren las 24 celdas corregidas el 30/10/2026 (comentadas).
# 2. Agregar una capa P4 de:
#    - normalización de entrada
#    - búsqueda robusta
#    - sugerencias
#    - evaluación estructurada
# 3. Separar:
#    - compatibilidad de catálogo
#    - interpretación operativa P4
#
# Fuente base:
#   Tabla DMH (Material Chemical Compatibility.xlsx) y corrección Aero, ISM y Little Giant del 30/10/2026.
# =============================================================================

# IMPORTANTE:
# - No corregir nombres.
# - No fusionar entradas.
# - No traducir valores.
# - No reinterpretar compatibilidades.
# =============================================================================

# =============================================================================
# TAXONOMÍA MATERIAL P4
# -----------------------------------------------------------------------------
# Se define como lista oficial de materiales evaluables en esta capa.
# Si más adelante se amplía P4, este set se ajusta.
# =============================================================================

MATERIALES_P4_VALIDOS = {
    "HPU",
    "C-HPU",
    "NBR",
    "H-NBR",
    "EPDM",
    "MVQ",
    "FPM",
    "AFLAS",
    "PTFE",
    "POM",
    "PA",
    "UHMWPE",
}

# Alias mínimos de materiales para integración robusta.
# No toca el catálogo fuente; solo facilita la entrada del usuario.
_EQUIVALENCIAS_MATERIALES = {
    "DMH_100_HPU": "HPU",
    "DMH 100 HPU": "HPU",

    "DMH_120_C_HPU": "C-HPU",
    "DMH 120 C-HPU": "C-HPU",
  
    "DMH_300_NBR": "NBR",
    "DMH 300 NBR": "NBR",

    "DMH_310_HNBR": "H-NBR",
    "DMH 310 HNBR": "H-NBR",

    "DMH_330_EPDM": "EPDM",
    "DMH 330 EPDM": "EPDM",

    "DMH_340_MVQ": "MVQ",
    "DMH 340 MVQ": "MVQ",

    "DMH_356_FPM": "FPM",
    "DMH 356 FPM": "FPM",

    "DMH_360_TFE_P": "AFLAS",
    "DMH 360 TFE/P": "AFLAS",

    "DMH_400_POM": "POM",
    "DMH 400 POM": "POM",

    "DMH_410_PA6": "PA",
    "DMH 410 PA6": "PA",

    "DMH_420_UHMW_PE": "UHMWPE",
    "DMH 420 UHMW-PE": "UHMWPE",

    "DMH_600_PTFE": "PTFE",
    "DMH 600 PTFE": "PTFE",

    "DMH_601_PTFE_D05": "PTFE",
    "DMH 601 PTFE D05": "PTFE",

    "DMH_610_PTFE_I": "PTFE",
    "DMH 610 PTFE I": "PTFE",

    "DMH_613_PTFE_25G": "PTFE",
    "DMH 613 PTFE 25% Glass": "PTFE",

    "DMH_622_PTFE_BZ60": "PTFE",
    "DMH 622 PTFE BZ 60%": "PTFE",
}


# =============================================================================
# NORMALIZACIÓN
# -----------------------------------------------------------------------------
# Regla:
# - normalizar FORMA
# - no destruir SIGNIFICADO técnico
#
# Se preservan:
# - números
# - porcentajes
# - palabras técnicas
# - condiciones (HOT, COLD, AQ, ANHYDROUS, etc.)
# =============================================================================

def normalizar_nombre_fluido(texto: str) -> str:
    """
    Normaliza la entrada del fluido para búsqueda robusta, sin alterar
    el significado técnico del catálogo.

    Acciones:
    - strip
    - upper
    - reemplazo controlado de guiones y comas por espacio
    - colapso de espacios múltiples
    """
    if not isinstance(texto, str):
        raise TypeError("El nombre del fluido debe ser str.")

    texto = texto.strip().upper()
    texto = texto.replace("-", " ")
    texto = texto.replace(",", " ")
    texto = re.sub(r"\s+", " ", texto)
    return texto


def normalizar_material(material: str) -> str:
    """
    Normaliza material de entrada sin alterar la taxonomía oficial.
    """
    if not isinstance(material, str):
        raise TypeError("El material debe ser str.")

    valor = material.strip().upper()
    valor = _EQUIVALENCIAS_MATERIALES.get(valor, valor)
    return valor


# =============================================================================
# ÍNDICE NORMALIZADO CACHEADO
# -----------------------------------------------------------------------------
# Se construye una sola vez al cargar el módulo.
# No se recalcula en cada consulta.
# =============================================================================

def construir_indice_normalizado(catalogo: Dict[str, Dict[str, str]]) -> Dict[str, List[str]]:
    """
    Construye un índice:
        nombre_normalizado -> [nombres_originales_catalogo]

    Se usa lista porque distintas claves originales podrían colisionar al
    normalizar forma. No se asume unicidad destructiva.
    """
    indice: Dict[str, List[str]] = {}

    for nombre_original in catalogo.keys():
        nombre_norm = normalizar_nombre_fluido(nombre_original)
        indice.setdefault(nombre_norm, []).append(nombre_original)

    return indice


INDICE_FLUIDOS_NORMALIZADO = construir_indice_normalizado(compatibilidad_fluido_material)


# =============================================================================
# UTILIDADES
# =============================================================================

def material_es_valido(material: str) -> bool:
    return normalizar_material(material) in MATERIALES_P4_VALIDOS


def fluido_existe_en_catalogo(nombre_fluido: str) -> bool:
    nombre_norm = normalizar_nombre_fluido(nombre_fluido)
    return nombre_norm in INDICE_FLUIDOS_NORMALIZADO


def obtener_fluidos_catalogo() -> List[str]:
    return list(compatibilidad_fluido_material.keys())


def obtener_materiales_catalogo() -> List[str]:
    if not compatibilidad_fluido_material:
        return []
    primer_fluido = next(iter(compatibilidad_fluido_material))
    return list(compatibilidad_fluido_material[primer_fluido].keys())


# =============================================================================
# BÚSQUEDA DE FLUIDO
# -----------------------------------------------------------------------------
# Estrategia:
# 1. coincidencia exacta normalizada
# 2. si hay una sola coincidencia, devolverla
# 3. si hay varias, devolver ambigüedad controlada
# 4. si no hay coincidencia, sugerir opciones cercanas
# =============================================================================

def buscar_fluido_en_catalogo(
    nombre_usuario: str,
    max_sugerencias: int = 5,
    cutoff: float = 0.60,
) -> Dict[str, Any]:
    """
    Busca el fluido en el catálogo del proveedor con lógica segura.
    """
    nombre_usuario_norm = normalizar_nombre_fluido(nombre_usuario)

    # 1) Match exacto normalizado
    coincidencias_exactas = INDICE_FLUIDOS_NORMALIZADO.get(nombre_usuario_norm, [])

    if len(coincidencias_exactas) == 1:
        return {
            "encontrado": True,
            "ambiguo": False,
            "nombre_catalogo": coincidencias_exactas[0],
            "coincidencias": coincidencias_exactas,
            "sugerencias": [],
            "mensaje": "Coincidencia exacta encontrada.",
        }

    if len(coincidencias_exactas) > 1:
        return {
            "encontrado": False,
            "ambiguo": True,
            "nombre_catalogo": None,
            "coincidencias": coincidencias_exactas,
            "sugerencias": coincidencias_exactas,
            "mensaje": (
                "La entrada coincide con múltiples nombres del catálogo. "
                "Se requiere selección explícita."
            ),
        }

    # 2) Sugerencias cercanas
    candidatos_norm = list(INDICE_FLUIDOS_NORMALIZADO.keys())
    cercanos_norm = difflib.get_close_matches(
        nombre_usuario_norm,
        candidatos_norm,
        n=max_sugerencias,
        cutoff=cutoff,
    )

    sugerencias: List[str] = []
    for clave_norm in cercanos_norm:
        sugerencias.extend(INDICE_FLUIDOS_NORMALIZADO.get(clave_norm, []))

    # quitar duplicados preservando orden
    sugerencias_unicas = list(dict.fromkeys(sugerencias))

    return {
        "encontrado": False,
        "ambiguo": False,
        "nombre_catalogo": None,
        "coincidencias": [],
        "sugerencias": sugerencias_unicas,
        "mensaje": "No se encontró coincidencia exacta en el catálogo.",
    }


# =============================================================================
# CONSULTA DIRECTA DE COMPATIBILIDAD
# -----------------------------------------------------------------------------
# Devuelve el valor exacto del catálogo, sin reinterpretarlo.
# =============================================================================

def obtener_compatibilidad_catalogo(
    fluido: str,
    material: str,
) -> Dict[str, Any]:
    """
    Consulta el catálogo del proveedor y devuelve la compatibilidad exacta,
    sin reinterpretación.
    """
    resultado_busqueda = buscar_fluido_en_catalogo(fluido)
    material_norm = normalizar_material(material)

    if not material_es_valido(material_norm):
        return {
            "ok": False,
            "fluido_encontrado": False,
            "material_valido": False,
            "compatibilidad_catalogo": None,
            "nombre_catalogo": None,
            "mensaje": f"Material no reconocido en P4: {material}",
            "sugerencias_fluido": resultado_busqueda.get("sugerencias", []),
        }

    if not resultado_busqueda["encontrado"]:
        return {
            "ok": False,
            "fluido_encontrado": False,
            "material_valido": True,
            "compatibilidad_catalogo": None,
            "nombre_catalogo": None,
            "mensaje": resultado_busqueda["mensaje"],
            "sugerencias_fluido": resultado_busqueda.get("sugerencias", []),
            "coincidencias": resultado_busqueda.get("coincidencias", []),
            "ambiguo": resultado_busqueda.get("ambiguo", False),
        }

    nombre_catalogo = resultado_busqueda["nombre_catalogo"]
    tabla_materiales = compatibilidad_fluido_material.get(nombre_catalogo, {})

    if material_norm not in tabla_materiales:
        return {
            "ok": False,
            "fluido_encontrado": True,
            "material_valido": False,
            "compatibilidad_catalogo": None,
            "nombre_catalogo": nombre_catalogo,
            "mensaje": (
                f"El material '{material_norm}' no existe en la tabla del fluido "
                f"'{nombre_catalogo}'."
            ),
            "sugerencias_fluido": [],
        }

    return {
        "ok": True,
        "fluido_encontrado": True,
        "material_valido": True,
        "compatibilidad_catalogo": tabla_materiales[material_norm],
        "nombre_catalogo": nombre_catalogo,
        "mensaje": "Compatibilidad encontrada en catálogo.",
        "sugerencias_fluido": [],
    }


# =============================================================================
# MAPEO OPERATIVO P4
# -----------------------------------------------------------------------------
# Esta capa NO modifica el valor del catálogo.
# Solo lo interpreta operativamente para soporte a decisión.
# =============================================================================

MAPEO_COMPATIBILIDAD_P4 = {
    "EXCELENTE": {
        "estado": "Aceptable",
        "nivel": "Bajo",
        "requiere_validacion_tecnica": True,
        "observacion": "Compatibilidad alta según catálogo del proveedor.",
    },
    "BUENA": {
        "estado": "Aceptable",
        "nivel": "Bajo",
        "requiere_validacion_tecnica": True,
        "observacion": "Compatibilidad favorable; validar condiciones específicas de servicio.",
    },
    "REGULAR": {
        "estado": "Condicional",
        "nivel": "Medio",
        "requiere_validacion_tecnica": True,
        "observacion": "Compatibilidad condicionada; requiere validación técnica adicional.",
    },
    "NO COMPATIBLE": {
        "estado": "Crítico",
        "nivel": "Alto",
        "requiere_validacion_tecnica": True,
        "observacion": "Compatibilidad no aceptable según catálogo del proveedor.",
    },
    "SIN DATO DE LABORATORIO": {
        "estado": "No evaluable",
        "nivel": "Sin dato",
        "requiere_validacion_tecnica": True,
        "observacion": "No existe ensayo de laboratorio registrado para este par fluido-material. "
                        "Ausencia de dato: no debe interpretarse como compatibilidad ni como incompatibilidad. "
                        "Requiere validación técnica directa con el fabricante antes de decidir.",
    },
}


def interpretar_compatibilidad_p4(valor_catalogo: str) -> Dict[str, Any]:
    """
    Traduce el valor del catálogo a semántica operativa P4.
    """
    if not isinstance(valor_catalogo, str):
        raise TypeError("valor_catalogo debe ser str")

    clave = valor_catalogo.strip().upper()

    if clave not in MAPEO_COMPATIBILIDAD_P4:
        return {
            "estado": "Condicional",
            "nivel": "Medio",
            "requiere_validacion_tecnica": True,
            "observacion": (
                f"Valor de compatibilidad no mapeado explícitamente en P4: '{valor_catalogo}'. "
                "Requiere revisión manual."
            ),
        }

    return MAPEO_COMPATIBILIDAD_P4[clave].copy()


# =============================================================================
# EVALUACIÓN P4
# -----------------------------------------------------------------------------
# Devuelve salida estructurada para el sistema.
# =============================================================================

def evaluar_compatibilidad_fluido_material_p4(
    fluido: str,
    material: str,
    perfil: Optional[str] = None,
    presion: Optional[float] = None,
    temperatura: Optional[float] = None,
    velocidad: Optional[float] = None,
    gap: Optional[float] = None,
    backup: Optional[str] = None,
    medio: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Evalúa compatibilidad fluido-material bajo lógica P4.

    Esta función:
    - consulta la fuente del proveedor
    - preserva el valor exacto del catálogo
    - genera una interpretación operativa estructurada
    """
    consulta = obtener_compatibilidad_catalogo(fluido, material)
    alertas: List[str] = []
    observaciones: List[str] = []

    if not consulta["ok"]:
        # ANCLA_INICIO: ESTADO_HONESTO_MATERIAL_NO_CATALOGADO_P4
        # Antes: "Condicional" fijo para CUALQUIER falla, sin distinguir causa.
        # Material no reconocido en absoluto (ej. material de Sello adicional
        # comprado, no catalogado) es un caso distinto y más honesto que
        # "fluido no encontrado" (material sí válido, falla la búsqueda de
        # fluido) — CRITERIOS_DE_ENTRADA_P4 exige declarar "no evaluado",
        # no un estado intermedio que suena a resultado calculado.
        material_reconocido = consulta.get("material_valido", True)
        if not material_reconocido:
            estado_honesto = "No evaluado"
            nivel_honesto = "No evaluado"
            sugerencias_vacias = []
        else:
            estado_honesto = "Condicional"
            nivel_honesto = "Medio"
            sugerencias_vacias = consulta.get("sugerencias_fluido", [])
        return {
            "ok": False,
            "fluido_ingresado": fluido,
            "material_ingresado": material,
            "fluido_catalogo": consulta.get("nombre_catalogo"),
            "compatibilidad_catalogo": None,
            "estado": estado_honesto,
            "nivel": nivel_honesto,
            "requiere_validacion_tecnica": True,
            "alertas": [consulta["mensaje"]],
            "observaciones": [],
            "sugerencias_fluido": sugerencias_vacias,
            "coincidencias": consulta.get("coincidencias", []),
            "ambiguo": consulta.get("ambiguo", False),
            "fuente_a_validar": {
                "fluido": "Seleccionar nombre exacto del catálogo del proveedor",
                "material": normalizar_material(material),
        # ANCLA_FINAL: ESTADO_HONESTO_MATERIAL_NO_CATALOGADO_P4
                "catalogo": "Tabla proveedor DMH y corrección Aero, ISM y Little Giant",
            },
        }

    compatibilidad_catalogo = consulta["compatibilidad_catalogo"]
    interpretacion = interpretar_compatibilidad_p4(compatibilidad_catalogo)

    # Observaciones contextuales P4
    if perfil:
        observaciones.append(
            f"Perfil informado: {perfil}. La compatibilidad química no sustituye la validación geométrica del perfil."
        )
    if presion is not None:
        observaciones.append(
            f"Presión informada: {presion}. La compatibilidad química debe integrarse con presión, GAP y soporte."
        )
    if temperatura is not None:
        observaciones.append(
            f"Temperatura informada: {temperatura}. Validar con límites térmicos propios del material."
        )
    if velocidad is not None:
        observaciones.append(
            f"Velocidad informada: {velocidad}. Validar fricción, generación térmica y condiciones dinámicas."
        )
    if gap is not None:
        observaciones.append(
            f"GAP informado: {gap}. La compatibilidad química no reemplaza el análisis de extrusión."
        )
    if backup:
        observaciones.append(
            f"Back-up informado: {backup}. El back-up modifica extrusión, no la compatibilidad química del fluido."
        )
    if medio:
        observaciones.append(
            f"Medio informado: {medio}. Confirmar que coincide con el nombre exacto seleccionado del catálogo."
        )

    if interpretacion["estado"] == "Condicional":
        alertas.append(
            "Compatibilidad tipo 'Regular': requiere validación técnica adicional antes de decisión final."
        )

    if interpretacion["estado"] == "Crítico":
        alertas.append(
            "Compatibilidad 'No compatible': condición crítica según catálogo del proveedor."
        )

    return {
        "ok": True,
        "fluido_ingresado": fluido,
        "material_ingresado": material,
        "fluido_catalogo": consulta["nombre_catalogo"],
        "material_normalizado": normalizar_material(material),
        "compatibilidad_catalogo": compatibilidad_catalogo,
        "estado": interpretacion["estado"],
        "nivel": interpretacion["nivel"],
        "requiere_validacion_tecnica": interpretacion["requiere_validacion_tecnica"],
        "alertas": alertas,
        "observaciones": observaciones + [interpretacion["observacion"]],
        "fuente_a_validar": {
            "fluido": consulta["nombre_catalogo"],
            "material": normalizar_material(material),
            "catalogo": "Tabla proveedor DMH y corrección Aero, ISM y Little Giant",
        },
    }


# =============================================================================
# FUNCIONES DE APOYO PARA UI / INTEGRACIÓN
# =============================================================================

def sugerir_fluidos(nombre_usuario: str, max_sugerencias: int = 10) -> List[str]:
    resultado = buscar_fluido_en_catalogo(nombre_usuario, max_sugerencias=max_sugerencias)
    return resultado.get("sugerencias", [])


def resolver_fluido_o_listar_opciones(nombre_usuario: str) -> Dict[str, Any]:
    """
    Útil para UI:
    - si encuentra uno exacto, lo devuelve
    - si no, devuelve opciones
    """
    return buscar_fluido_en_catalogo(nombre_usuario)


